    <title>Tui</title>
    <style>
      :root {
        color-scheme: light;
        /* Warm paper shell — brand colors on boards & accents only */
        --bg-0: #eef2f8;
        --bg-1: #ffffff;
        --bg-2: #ffffff;
        --bg-3: #f3f6fb;
        --line: #e2e8f0;
        --line-strong: #cbd5e1;
        --ink: #0f172a;
        --muted: #64748b;
        --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.05), 0 1px 3px rgba(15, 23, 42, 0.04);
        --shadow-md: 0 4px 14px rgba(15, 23, 42, 0.08), 0 2px 6px rgba(15, 23, 42, 0.04);
        --shadow-window: 0 20px 50px rgba(15, 23, 42, 0.12), 0 8px 20px rgba(15, 23, 42, 0.06);

        /* Tui palette (canonical) */
        --golden-pollen: #ffc857;
        --crayola-blue: #3772ff;
        --scarlet-rush: #df2935;
        --jungle-green: #3bb273;

        /* Deeper stops for tiles, hovers, and game pieces */
        --golden-pollen-deep: #e6a830;
        --crayola-blue-deep: #2955c9;
        --scarlet-rush-deep: #b81f2a;
        --jungle-green-deep: #2e8f5c;

        /* Legacy aliases — gameplay CSS still references these names */
        --blue: var(--crayola-blue);
        --blue-deep: var(--crayola-blue-deep);
        --banana: var(--golden-pollen);
        --banana-deep: var(--golden-pollen-deep);
        --pumpkin: var(--jungle-green);
        --pumpkin-deep: var(--jungle-green-deep);
        --cinnabar: var(--scarlet-rush);
        --cinnabar-deep: var(--scarlet-rush-deep);

        /* Snake reads against a sage field and a red apple, so it sits off the
           arcade palette on purpose — violet clashes with neither. */
        --snake: #6d3bd4;

        /* roles */
        --accent: var(--golden-pollen);
        --accent-dim: rgba(255, 200, 87, .22);
        --accent-ink: #3d2e00;
        --title-gradient: var(--crayola-blue);
        --danger: var(--scarlet-rush);
        --gold: var(--golden-pollen);
        --success: var(--jungle-green);
        --hover: var(--jungle-green);
        --ink-on-pumpkin: #ffffff;
        --ink-on-blue: #ffffff;
        --ink-on-vivid: #ffffff;
        --radius-s: 6px;
        --radius-m: 10px;
        --radius-l: 16px;
        --window-radius: var(--radius-l);

        /* Motion tokens — every board animates on the same clock.
           --motion-travel is capped short because Snake ticks every 70ms. */
        --motion-fast: 90ms;
        --motion-travel: 120ms;
        --motion-base: 160ms;
        /* Board-wide gestures (a 2048 move slides many tiles at once) run
           slower than single-piece feedback, or they read as a flicker. */
        --motion-slide: 200ms;
        --motion-slow: 280ms;
        --motion-trail: 340ms;
        --ease-out: cubic-bezier(.22, .68, .35, 1);
        --ease-pop: cubic-bezier(.34, 1.56, .64, 1);
        --ease-in: cubic-bezier(.55, .06, .68, .19);
        --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
        --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, monospace;
      }

      * { box-sizing: border-box; }
      html, body {
        width: 100%;
        height: 100%;
        background: transparent;
      }
      body {
        margin: 0;
        overflow: hidden;
        color: var(--ink);
        font-family: var(--sans);
        user-select: none;
        -webkit-font-smoothing: antialiased;
      }

      button { font: inherit; }
      button:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }

      /* Flex column: hidden children (update banner) drop out cleanly. */
      .app {
        position: relative;
        height: 100%;
        display: flex;
        flex-direction: column;
        background: var(--bg-1);
        border: 1px solid rgba(255, 255, 255, 0.65);
        border-radius: var(--window-radius);
        overflow: hidden;
        box-shadow: var(--shadow-window);
      }
      .app > .titlebar, .app > .update-banner { flex: 0 0 auto; }
      .app > main { flex: 1 1 auto; }

      /* ── Titlebar ─────────────────────────────────────────────── */
      .titlebar {
        min-height: 48px;
        padding: 8px 10px 8px 16px;
        border-bottom: 1px solid var(--line);
        background: #ffffff;
        display: flex;
        align-items: center;
        gap: 10px;
        -webkit-app-region: drag;
      }

      .window-actions { margin-left: auto; display: flex; gap: 6px; }
      .window-actions, .window-actions button { -webkit-app-region: no-drag; }
      .window-actions button {
        min-width: 32px;
        height: 28px;
        padding: 0 9px;
        border: 1px solid transparent;
        border-radius: var(--radius-s);
        background: transparent;
        color: var(--muted);
        cursor: pointer;
        font-size: 13px;
        transition: background .12s ease, color .12s ease;
      }
      .window-actions button:hover,
      .window-actions button:focus-visible {
        background: var(--bg-3);
        color: var(--ink);
        outline: none;
      }
      #shutdown { color: rgba(223, 41, 53, .55); }
      #shutdown:hover, #shutdown:focus-visible { background: rgba(223, 41, 53, .14); color: var(--danger); }

      /* ── Update banner ────────────────────────────────────────── */
      .update-banner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 10px 14px;
        border-bottom: 1px solid var(--line);
        background: #fffbeb;
      }
      .update-banner[hidden] { display: none !important; }
      .update-copy { min-width: 0; }
      .update-label {
        margin: 0 0 2px;
        font: 600 11px/1.2 var(--sans);
        letter-spacing: .08em;
        text-transform: uppercase;
        color: var(--muted);
      }
      .update-versions {
        margin: 0;
        font: 500 13px/1.3 var(--mono);
        color: var(--ink);
      }
      .update-versions #update-to { color: var(--crayola-blue-deep); }
      .update-button {
        flex: 0 0 auto;
        height: 30px;
        padding: 0 12px;
        border: 1px solid var(--golden-pollen-deep);
        border-radius: var(--radius-s);
        background: var(--golden-pollen);
        color: var(--accent-ink);
        cursor: pointer;
        font: 600 12px/1 var(--sans);
        transition: background .12s ease, border-color .12s ease, box-shadow .12s ease;
        box-shadow: var(--shadow-sm);
      }
      .update-button:hover:not(:disabled),
      .update-button:focus-visible:not(:disabled) {
        background: var(--golden-pollen-deep);
        border-color: var(--golden-pollen-deep);
        outline: none;
      }
      .update-button:disabled { opacity: .55; cursor: default; }
      .update-button[hidden] { display: none !important; }
      /* Shown instead of the button when this install cannot upgrade itself. */
      .update-manual {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-top: 6px;
        min-width: 0;
      }
      .update-manual[hidden] { display: none !important; }
      .update-command {
        flex: 1 1 auto;
        min-width: 0;
        padding: 4px 7px;
        border: 1px solid var(--line);
        border-radius: var(--radius-s);
        background: rgba(255, 255, 255, .7);
        font: 500 11px/1.35 var(--mono);
        color: var(--ink);
        overflow-x: auto;
        white-space: nowrap;
        user-select: text;
      }
      .update-copy-button {
        flex: 0 0 auto;
        height: 24px;
        padding: 0 9px;
        border: 1px solid var(--line);
        border-radius: var(--radius-s);
        background: #fff;
        color: var(--ink);
        cursor: pointer;
        font: 600 11px/1 var(--sans);
      }
      .update-copy-button:hover,
      .update-copy-button:focus-visible {
        border-color: var(--golden-pollen-deep);
        background: var(--golden-pollen);
        outline: none;
      }
      .update-status {
        margin: 6px 0 0;
        font-size: 12px;
        line-height: 1.35;
        color: var(--muted);
      }
      .update-status[data-state="error"] { color: var(--scarlet-rush); }
      .update-status[data-state="done"] { color: var(--blue); }
      .update-banner[data-state="running"] .update-button { opacity: .7; }
      .update-tui-brand {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 20px;
        padding: 6px 14px;
        background: #f1f5f9;
        border: 1px solid #cbd5e1;
        border-radius: 20px;
        font: 700 13px/1 var(--sans);
