      }
      .update-loading[hidden] { display: none !important; }
      .update-loading-card {
        max-width: 320px;
        padding: 28px 24px;
        background: #ffffff;
        border: 1px solid #e2e8f0;
        border-radius: 16px;
        box-shadow:
          0 20px 25px -5px rgba(15, 23, 42, 0.08),
          0 8px 10px -6px rgba(15, 23, 42, 0.04);
      }
      .update-tui-logo {
        display: block;
        width: 64px;
        height: 64px;
        margin: 0 auto 20px;
        object-fit: contain;
        filter: drop-shadow(0 4px 12px rgba(15, 23, 42, 0.12));
        animation: logo-pulse 1.8s var(--ease-out) infinite alternate;
      }
      @keyframes logo-pulse {
        from { transform: scale(0.95); opacity: 0.9; }
        to { transform: scale(1.05); opacity: 1; }
      }
      .update-loading h2 {
        margin: 0 0 8px;
        font: 700 22px/1.15 var(--sans);
        color: #0f172a;
      }
      .update-loading p {
        margin: 0;
        font: 500 13px/1.5 var(--mono);
        color: #475569;
      }
      .update-loading .update-loading-note {
        margin-top: 14px;
        font: 500 12px/1.45 var(--sans);
        color: #64748b;
      }
      @keyframes update-block {
        from { transform: translateY(0); opacity: .45; }
        to { transform: translateY(-10px); opacity: 1; }
