      @media (prefers-reduced-motion: reduce) {
        .update-loader i { animation: none; opacity: 1; }
      }

      /* ── Account chip (titlebar, top-left, persistent) ────────── */
      .account-chip {
        -webkit-app-region: no-drag;
        display: inline-flex;
        align-items: center;
        gap: 7px;
        max-width: 220px;
        height: 28px;
        padding: 0 10px;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: var(--bg-1);
        color: var(--ink);
        cursor: pointer;
        font: 600 12px/1 var(--sans);
        box-shadow: var(--shadow-sm);
        transition: border-color .12s ease, background .12s ease, box-shadow .12s ease;
      }
      .account-chip[hidden] { display: none !important; }
      .account-chip:hover, .account-chip:focus-visible {
        border-color: var(--crayola-blue);
        background: var(--bg-3);
        box-shadow: var(--shadow-md);
        outline: none;
      }
      .account-chip .account-dot {
        width: 7px;
        height: 7px;
        flex: 0 0 auto;
        border-radius: 50%;
        background: var(--muted);
      }
      .account-chip[data-state="in"] .account-dot { background: var(--crayola-blue); }
      .account-chip[data-state="out"] .account-dot { background: var(--golden-pollen); }
      .account-chip[data-sync="error"] {
        border-color: var(--scarlet-rush);
      }
      .account-chip[data-sync="error"] .account-dot {
        background: var(--scarlet-rush);
      }
      .account-chip .account-email {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
      .account-chip[data-state="out"] .account-email { color: var(--muted); }
      .account-chip[data-sync="error"] .account-email { color: var(--scarlet-rush); }

      /* ── Welcome gate (signed-out landing) ────────────────────── */
      #screen[data-screen="gate"] {
