      .gate-screen {
        width: min(100%, 380px);
        margin: 0 auto;
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
      }
      .gate-heading {
        margin: 0 0 14px;
        justify-content: center;
      }
      .gate-heading .menu-heading p,
      .menu-heading p {
        color: var(--crayola-blue-deep);
        font-weight: 600;
