        color: var(--muted);
        font-size: 12px;
        line-height: 1.4;
        text-align: center;
      }
      .auth-signin-status:empty { display: none; }
      .auth-signin-status[data-state="error"] { color: var(--scarlet-rush); }
      .auth-signin-button {
        width: min(100%, 240px);
        height: 38px;
        padding: 0 24px;
        border: 1px solid var(--golden-pollen-deep);
        border-radius: 999px;
        background: var(--accent);
        color: var(--accent-ink);
        cursor: pointer;
        font: 700 13px/1 var(--sans);
        box-shadow: var(--shadow-md);
        transition: background .12s ease, border-color .12s ease, opacity .12s ease, transform .12s ease;
      }
      .auth-signin-button:hover:not(:disabled),
      .auth-signin-button:focus-visible:not(:disabled) {
