        min-width: 128px;
        height: 30px;
        padding: 0 18px;
        border: 1px solid transparent;
        border-radius: var(--radius-s);
        background: transparent;
        color: var(--muted);
        cursor: pointer;
        font: 600 12px/1 var(--sans);
        transition: background .12s ease, color .12s ease;
      }
      .auth-signin-cancel[hidden] { display: none !important; }
      .auth-signin-cancel:hover, .auth-signin-cancel:focus-visible {
        background: var(--bg-3);
        color: var(--ink);
        outline: none;
      }
      /* Recovery path when the OS opener fails silently (e.g. Arc's Little Arc
