        border-color: var(--golden-pollen-deep);
        outline: none;
      }
      .auth-fallback-url {
        width: 100%;
        max-height: 3.6em;
        overflow-y: auto;
        padding: 6px 8px;
        border-radius: 4px;
        background: var(--bg-3);
