        overflow-y: auto;
      }
      /* Three short cards centred in a tall frame float in the middle of
         nowhere; the mode list reads better hanging from the top. */
      #screen[data-screen="variations"] { align-content: start; padding-top: 8px; overflow-y: auto; }
      #screen[data-screen="game"] {
        align-content: stretch;
        grid-template-rows: auto minmax(0, 1fr);
        min-height: 0;
      }
      #screen[data-screen="game"][data-game="connect4"] {
