        height: 100%;
        min-height: 0;
        flex: 1 1 auto;
        display: flex;
        flex-direction: column;
      }
      main:has(#screen[data-screen="game"][data-game="restaurant-arena"]) {
        padding: 0;
        background: #2b2118;
        min-height: 0;
        overflow: hidden;
        display: flex;
        flex-direction: column;
      }
      .app:has(#screen[data-screen="game"][data-game="restaurant-arena"]) {
        border: none;
        border-radius: 0;
        box-shadow: none;
      }
      #screen[data-screen="game"][data-game="connect4"] .playing-heading {
        margin-bottom: 8px;
      }
      /* #screen otherwise centers its two rows (heading, game) as one block.
         For most games the board is a fixed size, so that just centers a
         small object inside a big frame — most of the window's height goes
         unused above and below rather than to the game. Stretching here, and
         letting .game-snake (below) own the full row hands that space back so
