        grid-template-rows: auto minmax(0, 1fr);
        align-content: stretch;
      }

      /* ── Menu ─────────────────────────────────────────────────── */
      .menu-heading { margin: 0 4px 14px; display: flex; align-items: flex-start; gap: 10px; }
      .inline-back {
        height: 32px;
        padding: 0 10px 0 6px;
        border: 1px solid transparent;
        border-radius: var(--radius-s);
        background: transparent;
        color: var(--muted);
        cursor: pointer;
        font-size: 14px;
        font-weight: 600;
        transition: background .12s ease, color .12s ease;
        margin-top: -4px;
      }
      .inline-back:hover,
      .inline-back:focus-visible {
        background: var(--bg-2);
        color: var(--ink);
        outline: none;
      }
      /* Resuming is a real action, so it reads as a button rather than the
         bare text link it used to share with the back arrow: a pill that sits
         clear of the wordmark, with the quiet verb ahead of the game's name. */
      .resume-button {
        margin-top: 12px;
        min-height: 32px;
        padding: 0 12px;
        display: inline-flex;
        align-items: center;
        gap: 7px;
        border: 1px solid var(--line);
        border-radius: var(--radius-s);
        background: var(--bg-1);
        box-shadow: var(--shadow-sm);
