export function loadSavedGame(storage: Storage = localStorage): SavedGame | null {
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const saved: unknown = JSON.parse(raw);
    return validSavedGame(saved) ? saved : null;
  } catch {
    return null;
  }
}

export function saveSavedGame(saved: SavedGame, storage: Storage = localStorage): void {
  storage.setItem(STORAGE_KEY, JSON.stringify(saved));
}

/** Drop the compact journal. Restart uses this; returning to the menu does not. */
export function clearSavedGame(storage: Storage = localStorage): void {
  storage.removeItem(STORAGE_KEY);
}

/**
 * A new run never reuses the seed of the run it replaces. Only a resumed
 * launch reads a stored seed back out.
 */
export function nextRunSeed(previous?: number): number {
  const bytes = new Uint32Array(1);
  let seed: number;
  do {
    crypto.getRandomValues(bytes);
    seed = bytes[0]!;
  } while (previous !== undefined && seed === previous);
  return seed >>> 0;
}

/**
 * Overlay session chrome, kept out of `app.ts` so pause/resume and the
 * window-key mapping can be unit tested without a DOM.
 *
 * Stop pauses an active run and raises the "agent needs you" card. The next
 * prompt resumes. SessionStart reset snaps back to the menu without touching
 * the saved run.
 */

export type HostLifecycleEvent = "pause" | "resume" | "reset";

export interface PauseState {
  /** True while the agent-stop card is up and gameplay input is held. */
  paused: boolean;
}

export const RUNNING: PauseState = { paused: false };
export const PAUSED: PauseState = { paused: true };

export function applyHostLifecycle(state: PauseState, event: HostLifecycleEvent): PauseState {
  if (event === "pause") return PAUSED;
  return RUNNING;
}

export function gameplayBlocked(state: PauseState): boolean {
  return state.paused;
}

export type OverlayChromeKey = "escape" | "enter" | "q" | "m" | "r";

export type OverlayChromeAction =
  | "hide"
  | "menu"
  | "continue"
  | "restart"
  | "close-help"
  | "confirm-signout"
  | "cancel-signout"
  | "swallow";

export type OverlayChromeScreen = "gate" | "menu" | "variations" | "scores" | "settings" | "game";

/**
 * Map a physical key onto overlay chrome. `null` means the key belongs to
 * the active screen (menu cursor, game controls, …).
 */
export function overlayChromeKey(input: {
  key: OverlayChromeKey;
  howToPlayOpen: boolean;
  signOutOpen: boolean;
  paused: boolean;
  screen: OverlayChromeScreen;
}): OverlayChromeAction | null {
  const { key, howToPlayOpen, signOutOpen, paused, screen } = input;
  if (howToPlayOpen) {
    if (key === "escape" || key === "enter" || key === "q") return "close-help";
    return "swallow";
  }
  if (signOutOpen) {
    if (key === "enter") return "confirm-signout";
    if (key === "escape" || key === "q") return "cancel-signout";
    return "swallow";
  }
  if (paused) {
    if (key === "escape" || key === "q" || key === "enter") return "hide";
    if (key === "m") return "menu";
    return "swallow";
  }
  if (key === "escape" || key === "q") {
    if (screen === "variations" || screen === "scores" || screen === "settings") return "menu";
    if (screen === "menu" || screen === "game") return "hide";
    return "swallow";
  }
  if (key === "r" && screen === "game") return "restart";
  if (key === "m" && screen === "game") return "menu";
  return null;
}

