import { describe, expect, test } from "bun:test";
import { MENU_GAMES } from "../src/games/registry.js";
import {
  clearSavedGame,
  loadSavedGame,
  nextRunSeed,
  restoreGame,
  saveSavedGame,
  type SavedGame,
} from "./persistence.js";

const STORAGE_KEY = "gamepigeon.arcade.active-game.v1";

function memoryStorage(): Storage {
  const data = new Map<string, string>();
  return {
    get length() { return data.size; },
    clear() { data.clear(); },
    getItem(key) { return data.get(key) ?? null; },
    key(index) { return [...data.keys()][index] ?? null; },
    removeItem(key) { data.delete(key); },
    setItem(key, value) { data.set(key, String(value)); },
  };
}

function sampleSave(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: "restaurant-arena",
    gameVersion: "1",
    variationId: "dinner-rush",
    seed: 42,
    actions: ["tick"],
    ...overrides,
  };
}

describe("active-game persistence", () => {
  test("round-trips one SavedGame under the documented key", () => {
    const storage = memoryStorage();
    const saved = sampleSave();
    saveSavedGame(saved, storage);
    expect(storage.getItem(STORAGE_KEY)).toBeTruthy();
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("rejects a malformed or over-long journal", () => {
    const storage = memoryStorage();
    storage.setItem(STORAGE_KEY, "not json");
    expect(loadSavedGame(storage)).toBeNull();
    saveSavedGame(sampleSave({ actions: Array.from({ length: 50_001 }, () => "tick") }), storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("clearSavedGame drops the record so a restart cannot resume it", () => {
    const storage = memoryStorage();
    saveSavedGame(sampleSave(), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("restoreGame rebuilds the same run action-by-action", () => {
    const entry = MENU_GAMES.find((item) => item.id === "restaurant-arena")!;
    const saved = sampleSave({ actions: ["tick", "tick"] });
    const restored = restoreGame(entry, saved);
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(["tick", "tick"]);
    expect(restored!.game.isOver()).toBe(false);
    const fresh = entry.create!("dinner-rush");
    fresh.reset(42);
    fresh.step("tick");
    fresh.step("tick");
    expect(restored!.game.state()).toEqual(fresh.state());
  });

  test("restoreGame refuses a different game or rules version", () => {
    const entry = MENU_GAMES.find((item) => item.id === "restaurant-arena")!;
    expect(restoreGame(entry, sampleSave({ gameId: "snake" }))).toBeNull();
    expect(restoreGame(entry, sampleSave({ gameVersion: "0" }))).toBeNull();
  });

  test("nextRunSeed is a fresh unsigned integer, never the seed it replaces", () => {
    const previous = 7;
    for (let index = 0; index < 8; index++) {
      const seed = nextRunSeed(previous);
      expect(Number.isInteger(seed)).toBe(true);
      expect(seed).toBeGreaterThanOrEqual(0);
      expect(seed).toBeLessThanOrEqual(0xffffffff);
      expect(seed).not.toBe(previous);
    }
  });
});

import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  PREVIEW_RESIZE_MESSAGE,
} from "./tauri-bridge.js";

describe("overlay frame sizes", () => {
  test("match the production compact, expanded, pill, and restore-floor sizes", () => {
