import { describe, expect, test } from "bun:test";
import {
  PAUSED,
  RUNNING,
  applyHostLifecycle,
  gameplayBlocked,
  overlayChromeKey,
} from "./pause-state.js";

describe("host pause / resume / reset", () => {
  test("Stop pauses an active run until the next prompt resumes it", () => {
    const paused = applyHostLifecycle(RUNNING, "pause");
    expect(paused).toEqual(PAUSED);
    expect(gameplayBlocked(paused)).toBe(true);
    expect(applyHostLifecycle(paused, "resume")).toEqual(RUNNING);
    expect(gameplayBlocked(RUNNING)).toBe(false);
  });

  test("a second pause is idempotent", () => {
    expect(applyHostLifecycle(PAUSED, "pause")).toEqual(PAUSED);
  });

  test("SessionStart reset clears the pause without leaving the card up", () => {
    expect(applyHostLifecycle(PAUSED, "reset")).toEqual(RUNNING);
    expect(applyHostLifecycle(RUNNING, "reset")).toEqual(RUNNING);
  });
});

describe("window chrome keys", () => {
  test("Esc and q minimize to the pill from the menu or a run", () => {
    expect(overlayChromeKey({ key: "escape", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "menu" })).toBe("hide");
    expect(overlayChromeKey({ key: "q", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "game" })).toBe("hide");
  });

  test("Esc on nested menus returns to the game list", () => {
    expect(overlayChromeKey({ key: "escape", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "variations" })).toBe("menu");
    expect(overlayChromeKey({ key: "q", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "settings" })).toBe("menu");
    expect(overlayChromeKey({ key: "escape", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "scores" })).toBe("menu");
  });

  test("r restarts a mid-run shift; m ends it back to the menu", () => {
    expect(overlayChromeKey({ key: "r", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "game" })).toBe("restart");
    expect(overlayChromeKey({ key: "m", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "game" })).toBe("menu");
    expect(overlayChromeKey({ key: "r", howToPlayOpen: false, signOutOpen: false, paused: false, screen: "menu" })).toBeNull();
  });

  test("while the agent-stop card is up, Esc hides and M returns to the menu", () => {
    expect(overlayChromeKey({ key: "escape", howToPlayOpen: false, signOutOpen: false, paused: true, screen: "game" })).toBe("hide");
    expect(overlayChromeKey({ key: "enter", howToPlayOpen: false, signOutOpen: false, paused: true, screen: "game" })).toBe("hide");
