    expect(overlayChromeKey({ key: "escape", howToPlayOpen: true, signOutOpen: false, paused: false, screen: "menu" })).toBe("close-help");
    expect(overlayChromeKey({ key: "enter", howToPlayOpen: true, signOutOpen: false, paused: false, screen: "menu" })).toBe("close-help");
