function chooseGame(index: number): void {
  const selected = MENU_GAMES[index];
  if (!selected || !isPlayable(selected)) return;
  cursor = index;
  entry = selected;
  variationCursor = 0;
  if (selected.variations.length <= 1) {
    startGame(selected, variationIdFor(selected));
    return;
  }
  screen = "variations";
  drawVariations();
}

function chooseVariation(index: number): void {
  if (!entry) return;
  const variation = entry.variations[index];
  if (!variation) return;
  variationCursor = index;
  startGame(entry, variation.id);
}

function handleVariationKey(key: Key): void {
  if (!entry) return;
  if (key === "up" || key === "left") variationCursor = (variationCursor - 1 + entry.variations.length) % entry.variations.length;
  else if (key === "down" || key === "right") variationCursor = (variationCursor + 1) % entry.variations.length;
  else if (key === "enter") { chooseVariation(variationCursor); return; }
  drawVariations();
}

function handleArenaUi(action: "menu" | "restart" | "help"): void {
  if (action === "menu") returnToMenu();
  else if (action === "restart") restartRun();
  else showHowToPlay();
}

function launchEntry(gameId: string, variationId?: string, resume = false): boolean {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  cursor = MENU_GAMES.findIndex((item) => item.id === selected.id);
  startGame(selected, variationIdFor(selected, variationId), { resume });
  return true;
}

function resumeSaved(): boolean {
  if (!savedGame) return false;
  return launchEntry(savedGame.gameId, savedGame.variationId, true);
}

function startGame(selected: GameEntry, variationId: string, opts: { resume?: boolean } = {}): void {
  if (!selected.create) return;
  stopWorkerOrchestrator();
  cancelTicks();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  hidePausePrompt();
  hideHowToPlay();
  pauseState = RUNNING;

  entry = selected;
  const resolvedVariation = variationIdFor(selected, variationId);
  variationCursor = Math.max(0, selected.variations.findIndex((variation) => variation.id === resolvedVariation));

  let nextGame: PlayableGame | undefined;
  let seed: number;
  let restoredActions: string[] = [];

  if (opts.resume && savedGame) {
    const restored = restoreGame(selected, savedGame);
    if (restored) {
      nextGame = restored.game;
      restoredActions = restored.actions;
      seed = savedGame.seed;
    }
  }

  if (!nextGame) {
    seed = nextRunSeed(opts.resume ? undefined : savedGame?.seed);
    nextGame = selected.create(resolvedVariation);
    nextGame.reset(seed);
    savedGame = {
      schemaVersion: 1,
      ownerId: ownerId(),
      gameId: selected.id,
      gameVersion: selected.version,
      variationId: resolvedVariation,
      seed,
      actions: [],
    };
    persistActiveGame();
  }

  game = nextGame;
  gameEnded = false;
  replaying = false;
  gameStartedAt = Date.now();
  actionsTaken = restoredActions.length;
  screen = "game";
  activeTrace = createOverlayTrace(selected, resolvedVariation, seed);
  sessionReceiptId = activeTrace.gameId;
  persistTrace(activeTrace);
  captureOverlayEvent("game.started", { game_type: selected.id, variation_id: resolvedVariation }, sessionReceiptId);
  renderGameScreen();
