function consumePendingLaunch(): void {
  const params = new URLSearchParams(window.location.search);
  const deepGame = params.get("game");
  if (deepGame && !pendingLaunch) pendingLaunch = { gameId: deepGame, variationId: params.get("variation") ?? undefined };
  if (pendingLaunch) {
    const launch = pendingLaunch;
    pendingLaunch = undefined;
    if (launchEntry(launch.gameId, launch.variationId)) return;
  }
  if (settings.resumeLastGame) resumeSaved();
}

function openArcade(user?: AuthUser): void {
  if (user) {
    const saved = loadSavedGame();
    savedGame = saved?.ownerId === user.id ? saved : undefined;
    unlockTui(user);
